65	bool ReadBufferFromS3::nextImpl()
66	{
67	    if (read_until_position)
68	    {
69	        if (read_until_position == offset)
70	            return false;
71	
72	        if (read_until_position < offset)
73	            throw Exception(ErrorCodes::LOGICAL_ERROR, "Attempt to read beyond right offset ({} > {})", offset, read_until_position - 1);
74	    }
75	
76	    bool next_result = false;
77	
78	    if (impl)
79	    {
80	        if (use_external_buffer)
81	        {
82	            /**
83	            * use_external_buffer -- means we read into the buffer which
84	            * was passed to us from somewhere else. We do not check whether
85	            * previously returned buffer was read or not (no hasPendingData() check is needed),
86	            * because this branch means we are prefetching data,
87	            * each nextImpl() call we can fill a different buffer.
88	            */
89	            impl->set(internal_buffer.begin(), internal_buffer.size());
90	            assert(working_buffer.begin() != nullptr);
91	            assert(!internal_buffer.empty());
92	        }
93	        else
94	        {
95	            /**
96	            * impl was initialized before, pass position() to it to make
97	            * sure there is no pending data which was not read.
98	            */
99	            impl->position() = position();
100	            assert(!impl->hasPendingData());
101	        }
102	    }
103	
104	    size_t sleep_time_with_backoff_milliseconds = 100;
105	    for (size_t attempt = 0; (attempt < max_single_read_retries) && !next_result; ++attempt)
106	    {
107	        Stopwatch watch;
108	        try
109	        {
110	            if (!impl)
111	            {
112	                impl = initialize();
113	
114	                if (use_external_buffer)
115	                {
116	                    impl->set(internal_buffer.begin(), internal_buffer.size());
117	                    assert(working_buffer.begin() != nullptr);
118	                    assert(!internal_buffer.empty());
119	                }
120	                else
121	                {
122	                    /// use the buffer returned by `impl`
123	                    BufferBase::set(impl->buffer().begin(), impl->buffer().size(), impl->offset());
124	                }
125	            }
126	
127	            /// Try to read a next portion of data.
128	            next_result = impl->next();
129	            watch.stop();
130	            ProfileEvents::increment(ProfileEvents::ReadBufferFromS3Microseconds, watch.elapsedMicroseconds());
131	            break;
132	        }
133	        catch (const Exception & e)
134	        {
135	            watch.stop();
136	            ProfileEvents::increment(ProfileEvents::ReadBufferFromS3Microseconds, watch.elapsedMicroseconds());
137	            ProfileEvents::increment(ProfileEvents::ReadBufferFromS3RequestsErrors, 1);
138	
139	            LOG_DEBUG(
140	                log,
141	                "Caught exception while reading S3 object. Bucket: {}, Key: {}, Version: {}, Offset: {}, Attempt: {}, Message: {}",
142	                bucket,
143	                key,
144	                version_id.empty() ? "Latest" : version_id,
145	                getPosition(),
146	                attempt,
147	                e.message());
148	
149	            if (attempt + 1 == max_single_read_retries)
150	                throw;
151	
152	            /// Pause before next attempt.
153	            sleepForMilliseconds(sleep_time_with_backoff_milliseconds);
154	            sleep_time_with_backoff_milliseconds *= 2;
155	
156	            /// Try to reinitialize `impl`.
157	            impl.reset();
158	        }
159	    }
160	
161	    if (!next_result)
162	        return false;
163	
164	    BufferBase::set(impl->buffer().begin(), impl->buffer().size(), impl->offset());
165	
166	    ProfileEvents::increment(ProfileEvents::ReadBufferFromS3Bytes, working_buffer.size());
167	    offset += working_buffer.size();
168	    if (read_settings.remote_throttler)
169	        read_settings.remote_throttler->add(working_buffer.size());
170	
171	    return true;
172	}
