175	off_t ReadBufferFromS3::seek(off_t offset_, int whence)
176	{
177	    if (offset_ == offset && whence == SEEK_SET)
178	        return offset;
179	
180	    if (impl && restricted_seek)
181	        throw Exception(
182	            ErrorCodes::CANNOT_SEEK_THROUGH_FILE,
183	            "Seek is allowed only before first read attempt from the buffer (current offset: {}, new offset: {}, reading until position: {}, available: {})",
184	            offset, offset_, read_until_position, available());
185	
186	    if (whence != SEEK_SET)
187	        throw Exception("Only SEEK_SET mode is allowed.", ErrorCodes::CANNOT_SEEK_THROUGH_FILE);
188	
189	    if (offset_ < 0)
190	        throw Exception("Seek position is out of bounds. Offset: " + std::to_string(offset_), ErrorCodes::SEEK_POSITION_OUT_OF_BOUND);
191	
192	    if (!restricted_seek)
193	    {
194	        if (!working_buffer.empty()
195	            && static_cast<size_t>(offset_) >= offset - working_buffer.size()
196	            && offset_ < offset)
197	        {
198	            pos = working_buffer.end() - (offset - offset_);
199	            assert(pos >= working_buffer.begin());
200	            assert(pos <= working_buffer.end());
201	
202	            return getPosition();
203	        }
204	
205	        auto position = getPosition();
206	        if (offset_ > position)
207	        {
208	            size_t diff = offset_ - position;
209	            if (diff < read_settings.remote_read_min_bytes_for_seek)
210	            {
211	                ignore(diff);
212	                return offset_;
213	            }
214	        }
215	
216	        resetWorkingBuffer();
217	        if (impl)
218	        {
219	            ProfileEvents::increment(ProfileEvents::ReadBufferSeekCancelConnection);
220	            impl.reset();
221	        }
222	    }
223	
224	    offset = offset_;
225	    return offset;
226	}
