274	        if (offset >= read_until_position)
275	            throw Exception(ErrorCodes::LOGICAL_ERROR, "Attempt to read beyond right offset ({} > {})", offset, read_until_position - 1);
276	
277	        req.SetRange(fmt::format("bytes={}-{}", offset, read_until_position - 1));
278	        LOG_TEST(
