280	            "Read S3 object. Bucket: {}, Key: {}, Version: {}, Range: {}-{}",
281	            bucket,
282	            key,
283	            version_id.empty() ? "Latest" : version_id,
284	            offset,
285	            read_until_position - 1);
286	    }
287	    else
288	    {
289	        if (offset)
290	            req.SetRange(fmt::format("bytes={}-", offset));
291	        LOG_TEST(
292	            log,
293	            "Read S3 object. Bucket: {}, Key: {}, Version: {}, Offset: {}",
294	            bucket,
295	            key,
296	            version_id.empty() ? "Latest" : version_id,
297	            offset);
298	    }
299	
