81	void WriteBufferFromS3::nextImpl()
82	{
83	    if (!offset())
84	        return;
85	
86	    /// Buffer in a bad state after exception
87	    if (temporary_buffer->tellp() == -1)
88	        allocateBuffer();
89	
90	    size_t size = offset();
91	    temporary_buffer->write(working_buffer.begin(), size);
92	
93	    ThreadGroupStatusPtr running_group = CurrentThread::isInitialized() && CurrentThread::get().getThreadGroup()
94	            ? CurrentThread::get().getThreadGroup()
95	            : MainThreadStatus::getInstance().getThreadGroup();
96	
97	    if (cacheEnabled())
98	    {
99	        auto cache_key = cache->hash(key);
100	
101	        file_segments_holder.emplace(cache->setDownloading(cache_key, current_download_offset, size, /* is_persistent */false));
102	        current_download_offset += size;
103	
104	        size_t remaining_size = size;
105	        auto & file_segments = file_segments_holder->file_segments;
106	        for (auto file_segment_it = file_segments.begin(); file_segment_it != file_segments.end(); ++file_segment_it)
107	        {
108	            auto & file_segment = *file_segment_it;
109	            size_t current_size = std::min(file_segment->range().size(), remaining_size);
110	            remaining_size -= current_size;
111	
112	            if (file_segment->reserve(current_size))
113	            {
114	                file_segment->writeInMemory(working_buffer.begin(), current_size);
115	            }
116	            else
117	            {
118	                for (auto reset_segment_it = file_segment_it; reset_segment_it != file_segments.end(); ++reset_segment_it)
119	                    (*reset_segment_it)->complete(FileSegment::State::PARTIALLY_DOWNLOADED_NO_CONTINUATION);
120	                file_segments.erase(file_segment_it, file_segments.end());
121	                break;
122	            }
123	        }
124	    }
125	
126	    ProfileEvents::increment(ProfileEvents::WriteBufferFromS3Bytes, offset());
127	    last_part_size += offset();
128	    if (write_settings.remote_throttler)
129	        write_settings.remote_throttler->add(offset());
130	
131	    /// Data size exceeds singlepart upload threshold, need to use multipart upload.
132	    if (multipart_upload_id.empty() && last_part_size > s3_settings.max_single_part_upload_size)
133	        createMultipartUpload();
134	
135	    if (!multipart_upload_id.empty() && last_part_size > upload_part_size)
136	    {
137	        writePart();
138	
139	        allocateBuffer();
140	        file_segments_holder.reset();
141	    }
142	
143	    waitForReadyBackGroundTasks();
144	}
