232	void WriteBufferFromS3::writePart()
233	{
234	    auto size = temporary_buffer->tellp();
235	
236	    LOG_TRACE(log, "Writing part. Bucket: {}, Key: {}, Upload_id: {}, Size: {}", bucket, key, multipart_upload_id, size);
237	
238	    if (size < 0)
239	    {
240	        LOG_WARNING(log, "Skipping part upload. Buffer is in bad state, it means that we have tried to upload something, but got an exception.");
241	        return;
242	    }
243	
244	    if (size == 0)
245	    {
246	        LOG_TRACE(log, "Skipping writing part. Buffer is empty.");
247	        return;
248	    }
249	
250	    if (part_tags.size() == S3_WARN_MAX_PARTS)
251	    {
252	        // Don't throw exception here by ourselves but leave the decision to take by S3 server.
253	        LOG_WARNING(log, "Maximum part number in S3 protocol has reached (too many parts). Server may not accept this whole upload.");
254	    }
255	
256	    if (schedule)
257	    {
258	        UploadPartTask * task = nullptr;
259	        int part_number;
260	        {
261	            std::lock_guard lock(bg_tasks_mutex);
262	            task = &upload_object_tasks.emplace_back();
263	            ++num_added_bg_tasks;
264	            part_number = num_added_bg_tasks;
265	        }
266	
267	        fillUploadRequest(task->req, part_number);
268	
269	        if (file_segments_holder)
270	        {
271	            task->cache_files.emplace(std::move(*file_segments_holder));
272	            file_segments_holder.reset();
273	        }
274	
275	        schedule([this, task]()
276	        {
277	            try
278	            {
279	                processUploadRequest(*task);
280	            }
281	            catch (...)
282	            {
283	                task->exception = std::current_exception();
284	            }
285	
286	            try
287	            {
288	                finalizeCacheIfNeeded(task->cache_files);
289	            }
290	            catch (...)
291	            {
292	                tryLogCurrentException(__PRETTY_FUNCTION__);
293	            }
294	
295	            {
296	                std::lock_guard lock(bg_tasks_mutex);
297	                task->is_finised = true;
298	                ++num_finished_bg_tasks;
299	
300	                /// Notification under mutex is important here.
301	                /// Otherwise, WriteBuffer could be destroyed in between
302	                /// Releasing lock and condvar notification.
303	                bg_tasks_condvar.notify_one();
304	            }
305	        });
306	    }
307	    else
308	    {
309	        UploadPartTask task;
310	        fillUploadRequest(task.req, part_tags.size() + 1);
311	        if (file_segments_holder)
312	        {
313	            task.cache_files.emplace(std::move(*file_segments_holder));
314	            file_segments_holder.reset();
315	        }
316	        processUploadRequest(task);
317	        part_tags.push_back(task.tag);
318	        finalizeCacheIfNeeded(task.cache_files);
319	    }
320	}
