383	void WriteBufferFromS3::makeSinglepartUpload()
384	{
385	    auto size = temporary_buffer->tellp();
386	    bool with_pool = static_cast<bool>(schedule);
387	
388	    LOG_TRACE(log, "Making single part upload. Bucket: {}, Key: {}, Size: {}, WithPool: {}", bucket, key, size, with_pool);
389	
390	    if (size < 0)
391	    {
392	        LOG_WARNING(log, "Skipping single part upload. Buffer is in bad state, it mean that we have tried to upload something, but got an exception.");
393	        return;
394	    }
395	
396	    if (schedule)
397	    {
398	        put_object_task = std::make_unique<PutObjectTask>();
399	
400	        fillPutRequest(put_object_task->req);
401	        if (file_segments_holder)
402	        {
403	            put_object_task->cache_files.emplace(std::move(*file_segments_holder));
404	            file_segments_holder.reset();
405	        }
406	
407	        schedule([this]()
408	        {
409	            try
410	            {
411	                processPutRequest(*put_object_task);
412	            }
413	            catch (...)
414	            {
415	                put_object_task->exception = std::current_exception();
416	            }
417	
418	            try
419	            {
420	                finalizeCacheIfNeeded(put_object_task->cache_files);
421	            }
422	            catch (...)
423	            {
424	                tryLogCurrentException(__PRETTY_FUNCTION__);
425	            }
426	
427	            {
428	                std::lock_guard lock(bg_tasks_mutex);
429	                put_object_task->is_finised = true;
430	
431	                /// Notification under mutex is important here.
432	                /// Othervies, WriteBuffer could be destroyed in between
433	                /// Releasing lock and condvar notification.
434	                bg_tasks_condvar.notify_one();
435	            }
436	        });
437	    }
438	    else
439	    {
440	        PutObjectTask task;
441	        fillPutRequest(task.req);
442	        if (file_segments_holder)
443	        {
444	            task.cache_files.emplace(std::move(*file_segments_holder));
445	            file_segments_holder.reset();
446	        }
447	        processPutRequest(task);
448	        finalizeCacheIfNeeded(task.cache_files);
449	    }
450	}
