452	void WriteBufferFromS3::fillPutRequest(Aws::S3::Model::PutObjectRequest & req)
453	{
454	    req.SetBucket(bucket);
455	    req.SetKey(key);
456	    req.SetContentLength(temporary_buffer->tellp());
457	    req.SetBody(temporary_buffer);
458	    if (object_metadata.has_value())
459	        req.SetMetadata(object_metadata.value());
460	
461	    /// If we don't do it, AWS SDK can mistakenly set it to application/xml, see https://github.com/aws/aws-sdk-cpp/issues/1840
462	    req.SetContentType("binary/octet-stream");
463	}
