475	void WriteBufferFromS3::finalizeCacheIfNeeded(std::optional<FileSegmentsHolder> & file_segments_holder)
476	{
477	    if (!file_segments_holder)
478	        return;
479	
480	    auto & file_segments = file_segments_holder->file_segments;
481	    for (auto file_segment_it = file_segments.begin(); file_segment_it != file_segments.end();)
482	    {
483	        try
484	        {
485	            size_t size = (*file_segment_it)->finalizeWrite();
486	            file_segment_it = file_segments.erase(file_segment_it);
487	
488	            ProfileEvents::increment(ProfileEvents::CachedReadBufferCacheWriteBytes, size);
489	        }
490	        catch (...)
491	        {
492	            tryLogCurrentException(__PRETTY_FUNCTION__);
493	        }
494	    }
495	}
