51	template <typename Result, typename Error>
52	void throwIfError(const Aws::Utils::Outcome<Result, Error> & response)
53	{
54	    if (!response.IsSuccess())
55	    {
56	        const auto & err = response.GetError();
57	        throw Exception(ErrorCodes::S3_ERROR, "{} (Code: {})", err.GetMessage(), static_cast<size_t>(err.GetErrorType()));
58	    }
59	}
