61	template <typename Result, typename Error>
62	void throwIfUnexpectedError(const Aws::Utils::Outcome<Result, Error> & response, bool if_exists)
63	{
64	    /// In this case even if absence of key may be ok for us,
65	    /// the log will be polluted with error messages from aws sdk.
66	    /// Looks like there is no way to suppress them.
67	
68	    if (!response.IsSuccess() && (!if_exists || !isNotFoundError(response.GetError().GetErrorType())))
69	    {
70	        const auto & err = response.GetError();
71	        throw Exception(ErrorCodes::S3_ERROR, "{} (Code: {})", err.GetMessage(), static_cast<size_t>(err.GetErrorType()));
72	    }
73	}
