158	        return std::make_unique<AsynchronousReadIndirectBufferFromRemoteFS>(reader, disk_read_settings, std::move(s3_impl));
159	    }
160	    else
161	    {
162	        auto buf = std::make_unique<ReadIndirectBufferFromRemoteFS>(std::move(s3_impl));
163	        return std::make_unique<SeekAvoidingReadBuffer>(std::move(buf), settings_ptr->min_bytes_for_seek);
