183	std::unique_ptr<WriteBufferFromFileBase> S3ObjectStorage::writeObject( /// NOLINT
184	    const StoredObject & object,
185	    WriteMode mode, // S3 doesn't support append, only rewrite
186	    std::optional<ObjectAttributes> attributes,
187	    FinalizeCallback && finalize_callback,
188	    size_t buf_size,
189	    const WriteSettings & write_settings)
190	{
191	    WriteSettings disk_write_settings = IObjectStorage::patchSettings(write_settings);
192	
193	    if (mode != WriteMode::Rewrite)
194	        throw Exception(ErrorCodes::BAD_ARGUMENTS, "S3 doesn't support append to files");
195	
196	    bool cache_on_write = cache
197	         && write_settings.enable_filesystem_cache_on_write_operations
198	         && FileCacheFactory::instance().getSettings(getCacheBasePath()).cache_on_write_operations;
199	
200	    auto settings_ptr = s3_settings.get();
201	    auto s3_buffer = std::make_unique<WriteBufferFromS3>(
202	        client.get(),
203	        bucket,
204	        object.absolute_path,
205	        settings_ptr->s3_settings,
206	        attributes,
207	        buf_size,
208	        threadPoolCallbackRunner(getThreadPoolWriter()),
209	        disk_write_settings,
210	        cache_on_write ? cache : nullptr);
211	
212	
213	    return std::make_unique<WriteIndirectBufferFromRemoteFS>(
214	        std::move(s3_buffer), std::move(finalize_callback), object.absolute_path);
215	}
