217	void S3ObjectStorage::listPrefix(const std::string & path, RelativePathsWithSize & children) const
218	{
219	    auto settings_ptr = s3_settings.get();
220	    auto client_ptr = client.get();
221	
222	    Aws::S3::Model::ListObjectsV2Request request;
223	    request.SetBucket(bucket);
224	    request.SetPrefix(path);
225	    request.SetMaxKeys(settings_ptr->list_object_keys_size);
226	
227	    Aws::S3::Model::ListObjectsV2Outcome outcome;
228	    do
229	    {
230	        outcome = client_ptr->ListObjectsV2(request);
231	        throwIfError(outcome);
232	
233	        auto result = outcome.GetResult();
234	        auto objects = result.GetContents();
235	
236	        if (objects.empty())
237	            break;
238	
239	        for (const auto & object : objects)
240	            children.emplace_back(object.GetKey(), object.GetSize());
241	
242	        request.SetContinuationToken(outcome.GetResult().GetNextContinuationToken());
243	    } while (outcome.GetResult().GetIsTruncated());
244	}
