258	void S3ObjectStorage::removeObjectsImpl(const StoredObjects & objects, bool if_exists)
259	{
260	    if (objects.empty())
261	        return;
262	
263	    if (!s3_capabilities.support_batch_delete)
264	    {
265	        for (const auto & object : objects)
266	            removeObjectImpl(object, if_exists);
267	    }
268	    else
269	    {
270	        auto client_ptr = client.get();
271	        auto settings_ptr = s3_settings.get();
272	
273	        size_t chunk_size_limit = settings_ptr->objects_chunk_size_to_delete;
274	        size_t current_position = 0;
275	
276	        while (current_position < objects.size())
277	        {
278	            std::vector<Aws::S3::Model::ObjectIdentifier> current_chunk;
279	            String keys;
280	            for (; current_position < objects.size() && current_chunk.size() < chunk_size_limit; ++current_position)
281	            {
282	                Aws::S3::Model::ObjectIdentifier obj;
283	                obj.SetKey(objects[current_position].absolute_path);
284	                current_chunk.push_back(obj);
285	
286	                if (!keys.empty())
287	                    keys += ", ";
288	                keys += objects[current_position].absolute_path;
289	            }
290	
291	            Aws::S3::Model::Delete delkeys;
292	            delkeys.SetObjects(current_chunk);
293	            Aws::S3::Model::DeleteObjectsRequest request;
294	            request.SetBucket(bucket);
295	            request.SetDelete(delkeys);
296	            auto outcome = client_ptr->DeleteObjects(request);
297	
298	            throwIfUnexpectedError(outcome, if_exists);
299	        }
300	    }
301	}
