355	void S3ObjectStorage::copyObjectImpl(
356	    const String & src_bucket,
357	    const String & src_key,
358	    const String & dst_bucket,
359	    const String & dst_key,
360	    std::optional<Aws::S3::Model::HeadObjectResult> head,
361	    std::optional<ObjectAttributes> metadata) const
362	{
363	    auto client_ptr = client.get();
364	    Aws::S3::Model::CopyObjectRequest request;
365	    request.SetCopySource(src_bucket + "/" + src_key);
366	    request.SetBucket(dst_bucket);
367	    request.SetKey(dst_key);
368	    if (metadata)
369	    {
370	        request.SetMetadata(*metadata);
371	        request.SetMetadataDirective(Aws::S3::Model::MetadataDirective::REPLACE);
372	    }
373	
374	    auto outcome = client_ptr->CopyObject(request);
375	
376	    if (!outcome.IsSuccess() && outcome.GetError().GetExceptionName() == "EntityTooLarge")
377	    { // Can't come here with MinIO, MinIO allows single part upload for large objects.
378	        copyObjectMultipartImpl(src_bucket, src_key, dst_bucket, dst_key, head, metadata);
379	        return;
380	    }
381	
382	    throwIfError(outcome);
383	}
384	
385	void S3ObjectStorage::copyObjectMultipartImpl(
386	    const String & src_bucket,
387	    const String & src_key,
388	    const String & dst_bucket,
389	    const String & dst_key,
390	    std::optional<Aws::S3::Model::HeadObjectResult> head,
391	    std::optional<ObjectAttributes> metadata) const
392	{
393	    if (!head)
394	        head = requestObjectHeadData(src_bucket, src_key).GetResult();
395	
396	    auto settings_ptr = s3_settings.get();
397	    auto client_ptr = client.get();
398	    size_t size = head->GetContentLength();
399	
400	    String multipart_upload_id;
401	
402	    {
403	        Aws::S3::Model::CreateMultipartUploadRequest request;
404	        request.SetBucket(dst_bucket);
405	        request.SetKey(dst_key);
406	        if (metadata)
407	            request.SetMetadata(*metadata);
408	
409	        auto outcome = client_ptr->CreateMultipartUpload(request);
410	
411	        throwIfError(outcome);
412	
413	        multipart_upload_id = outcome.GetResult().GetUploadId();
414	    }
415	
416	    std::vector<String> part_tags;
417	
418	    size_t upload_part_size = settings_ptr->s3_settings.min_upload_part_size;
419	    for (size_t position = 0, part_number = 1; position < size; ++part_number, position += upload_part_size)
420	    {
421	        Aws::S3::Model::UploadPartCopyRequest part_request;
422	        part_request.SetCopySource(src_bucket + "/" + src_key);
423	        part_request.SetBucket(dst_bucket);
424	        part_request.SetKey(dst_key);
425	        part_request.SetUploadId(multipart_upload_id);
426	        part_request.SetPartNumber(part_number);
427	        part_request.SetCopySourceRange(fmt::format("bytes={}-{}", position, std::min(size, position + upload_part_size) - 1));
428	
429	        auto outcome = client_ptr->UploadPartCopy(part_request);
430	        if (!outcome.IsSuccess())
431	        {
432	            Aws::S3::Model::AbortMultipartUploadRequest abort_request;
433	            abort_request.SetBucket(dst_bucket);
434	            abort_request.SetKey(dst_key);
435	            abort_request.SetUploadId(multipart_upload_id);
436	            client_ptr->AbortMultipartUpload(abort_request);
437	            // In error case we throw exception later with first error from UploadPartCopy
438	        }
439	        throwIfError(outcome);
440	
441	        auto etag = outcome.GetResult().GetCopyPartResult().GetETag();
442	        part_tags.push_back(etag);
443	    }
444	
445	    {
446	        Aws::S3::Model::CompleteMultipartUploadRequest req;
447	        req.SetBucket(dst_bucket);
448	        req.SetKey(dst_key);
449	        req.SetUploadId(multipart_upload_id);
450	
451	        Aws::S3::Model::CompletedMultipartUpload multipart_upload;
452	        for (size_t i = 0; i < part_tags.size(); ++i)
453	        {
454	            Aws::S3::Model::CompletedPart part;
455	            multipart_upload.AddParts(part.WithETag(part_tags[i]).WithPartNumber(i + 1));
456	        }
457	
458	        req.SetMultipartUpload(multipart_upload);
459	
460	        auto outcome = client_ptr->CompleteMultipartUpload(req);
461	
462	        throwIfError(outcome);
